import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import { sha256Hex } from '@/lib/readiness/digest'
import { createV3ContextIdentity, createV3WorkIdentity, readV3GlobalRuleContext } from '../contract'

// Independent Root expectations captured before the C1 reader/mapper existed.
// These are literal fixtures, never generated by the implementation under test.
const legacyBytes = readFileSync('docs/official-truth-product-v3/C1_LEGACY_IDENTITIES_V1.json', 'utf8')
const revision2Bytes = readFileSync('docs/official-truth-product-v3/C1_REVISION2_IDENTITIES_V1.json', 'utf8')
const legacy = JSON.parse(legacyBytes) as { base: string; contractSha256: string; rows: Array<{ label: string; input: unknown; expected: unknown }> }
const revised = JSON.parse(revision2Bytes) as { rows: Array<{ label: string; context: unknown; canonicalPreimage: string;
  contextKey: string; ruleScopeKey: string; syntheticJob: { method: unknown; factKind: string; jobKey: string } }> }

test('C1 independent pre-change fixtures retain their original bytes and source binding', () => {
  assert.equal(sha256Hex(legacyBytes), '97b40395e44b8bc0608aff9262de022aa34ae18f7b1559f1c6762874336e6c4b')
  assert.equal(sha256Hex(revision2Bytes), 'd873b0a68e264330dd9d00bf6b3e7e4e263204b1e7755718c345b35c3331e03c')
  assert.equal(legacy.base, '0b704d0fa5d90031ca3ee80aabf2d8578d4cd2d5')
  assert.equal(legacy.contractSha256, '871b7eb7f4863fda0777593677b9bc265a0b6d22df99cc3caa2e1f0e59c672c4')
  assert.equal(legacy.rows.length, 6); assert.equal(revised.rows.length, 3)
})

for (const row of legacy.rows) test(`legacy exact scope/context/research/job identity: ${row.label}`, () => {
  const actual = createV3WorkIdentity(row.input)
  if (!actual.ok) assert.fail(actual.reason)
  assert.deepEqual(actual.value, row.expected)
})

for (const row of revised.rows) test(`revision2 matches independent explicit hash preimage: ${row.label}`, () => {
  assert.equal(`official-truth-context:v3:${sha256Hex(row.canonicalPreimage)}`, row.contextKey)
  const context = readV3GlobalRuleContext(row.context)
  if (!context.ok) assert.fail(context.reason)
  const actual = createV3ContextIdentity(context.value)
  if (!actual.ok) assert.fail(actual.reason)
  assert.deepEqual(actual.value, { contextKey: row.contextKey, ruleScopeKey: row.ruleScopeKey })
  const work = createV3WorkIdentity({ context: row.context, method: row.syntheticJob.method,
    factKind: row.syntheticJob.factKind, researchReason: { status: 'missing' } })
  if (!work.ok) assert.fail(work.reason)
  assert.equal(work.value.contextKey, row.contextKey)
  assert.equal(work.value.ruleScopeKey, row.ruleScopeKey)
  assert.equal(work.value.jobKey, row.syntheticJob.jobKey)
})

test('either inclusive bound changes full context/job identity while base scope remains the same', () => {
  assert.equal(new Set(revised.rows.map(row => row.ruleScopeKey)).size, 1)
  assert.equal(new Set(revised.rows.map(row => row.contextKey)).size, 3)
  assert.equal(new Set(revised.rows.map(row => row.syntheticJob.jobKey)).size, 3)
})
